// === Tab: Circle ===
class Circle {
	constructor(x, y, r, clr) {
		this.x = x;
		this.y = y;
		this.r = r;
		this.clr = clr;
	}

	overlaps(others, f = 1) {
		// just allow half radius overlapping to ensure space filling
		for (const o of others) {
			if (dist(this.x, this.y, o.x, o.y) < (this.r + o.r) * f) return true;
		}
		return false;
	}

	draw() {
		push();
			beginClip();
			noStroke();
			fill(255);
			circle(this.x, this.y, this.r + this.r);
			endClip();
			fill(this.clr);
			for (let xx = this.x - this.r; xx < this.x + this.r; xx += 3 * SCL) {
				rect(xx, 0, SCL, height);
			}
		pop();
	}
}

