const NUM = 5, BG = "tan";
const CLRS = ["grey", "blue", "darkgreen", "darkred", "darkorange", "cyan", "yellow", "orange"]
let S, SCL, circles;

function setup() {
	createCanvas(S=max(windowWidth, windowHeight), S);
	describe("bunch of overlapping circles out of striped lines")
	background("navy");
	// noLoop() removed for animation
}

function draw() {
	S=max(windowWidth, windowHeight)
	SCL = max(2, ~~(S/200));
	const colorMode = random() < 0.5;

	if (colorMode) {
		background("navy");
	} else {
		background(BG);
	}

	circles = [];
	for (let i = 0; i < 999; i++) {
		const clr =  colorMode ? CLRS[i % CLRS.length] : getColor();
		let tries = 99;
		for (; tries > 0; tries--) {		
			const x = ~~(random(-0.2, 1.2) * width);
			const y = ~~(random(-0.2, 1.2) * height);
			const r = ~~random(S/7, S/3);
			const circ = new Circle(x, y, r, clr);
			if (!circ.overlaps(circles, 0.45)) {
				circles.push(circ);
				circ.draw();
				break;
			}
		}
		// console.log(`${i}: ${tries} ${circles.length}`);
		if (tries <= 0) {
			// console.log("*", circles.length);
			break;
		}
	}
	// console.log(`circles: ${circles.length}`);
}

function getColor() {
	if (random() < 0.5) {
		return lerpColor(color(BG), color(0), random(0.3, 0.8));
	} else {
		return lerpColor(color(BG), color(255), random(0.3, 0.8));
	}
}

function mousePressed() {
	redraw();
}
function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
	redraw();
}
